"""Hydra boss (your two-headed hydra set: a fire head and an ice head). All frames face left.
(every other frame of your 41-frame animations, to keep memory down)
fly: wing-beat loop.  twin: both heads breathe in turn, fire and frost.  barrage: a gout of fire, then a spray of ice shards.
lunge: rears up and lunges forward breathing fire and frost together.  death: collapses into a heap of bones."""
import base64
import zlib
import pygame

HW, HH = 136, 124
HAX, HAY = 78, 62                    # body centre inside a frame
HEADS = [[(-51, 0), (-44, -1)], [(-54, -5), (-43, 0)], [(-55, -9), (-47, -17)], [(-51, -14), (-43, -4)], [(-52, -10), (-40, -7)], [(-50, -8), (-41, -1)], [(-52, -9), (-44, -1)], [(-55, 3), (-41, -4)], [(-54, 0), (-41, -3)], [(-51, -2), (-41, -3)], [(-50, -9), (-43, 0)], [(-54, -9), (-44, -1)], [(-54, -12), (-44, -11)], [(-50, -16), (-41, -4)], [(-52, -9), (-43, -2)], [(-50, -5), (-43, 0)], [(-51, -11), (-43, -1)], [(-54, 1), (-41, -3)], [(-54, 7), (-44, -3)], [(-50, -9), (-44, -2)], [(-51, -9), (-44, -18)]]                          # (fire mouth, ice mouth) offsets from the body centre for each flight frame (1x)
DEATH_BOTTOM = [34, 41, 41, 41, 42, 42, 42, 42, 42, 42, 42]                   # lowest pixel below the body centre in each death frame (1x)
HYD = {'fly': (21, ''), 'twin': (21, ''), 'death': (11, ''), 'barrage': (21, ''), 'lunge': (21, '')}
SCALE = 2.0
_C = {}


def hyd_frame(name, i, scale=SCALE, tint=None):
  n, data = HYD[name]
  i = max(0, min(n - 1, int(i))) if name in ('death', 'lunge') else int(i) % n
  k = (name, i, scale, tint)
  hit = _C.get(k)
  if hit is None:
    if tint:
      s0, ax, ay = hyd_frame(name, i, scale)
      s = s0.copy()
      s.fill((110, 110, 130) if tint == 'white' else (150, 0, 0), special_flags=pygame.BLEND_RGB_ADD)
      hit = _C[k] = (s, ax, ay)
      return hit
    raw = _C.get((name, 'raw'))
    if raw is None:
      raw = _C[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    m = HW * HH * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (HW, HH), 'RGBA').copy()
    if scale != 1:
      s = pygame.transform.scale(s, (int(HW * scale), int(HH * scale)))
    hit = _C[k] = (s, int(HAX * scale), int(HAY * scale))
  return hit


def hyd_mouths(b, scale=SCALE):
  """screen positions of the fire mouth and the ice mouth"""
  f, i = HEADS[int(b.get('fi', 0)) % len(HEADS)] if b.get('anim', 'fly') == 'fly' else HEADS[0]
  cx, cy = b['x'] + 75, b['y'] + 65
  return (cx + f[0] * scale, cy + f[1] * scale), (cx + i[0] * scale, cy + i[1] * scale)


def hyd_frames():
  return [hyd_frame('fly', i, 1.6)[0] for i in range(21)]
